    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int s = (int) in.nval;
        in.nextToken();
        int t = (int) in.nval;
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        int[] path = shortestPath(n, edges, s, t);
        if (path.length == 0) {
            System.out.println(-1);
            return;
        }
        StringBuilder sb = new StringBuilder();
        sb.append(path.length - 1).append("\n");
        for (int i = 0; i < path.length; i++) sb.append(path[i]).append(i + 1 < path.length ? " " : "\n");
        System.out.print(sb);
    }
}
